  #[using="sp Hn Happ Hs HG kL HkL"] Lemma c2_run : forall regs0 regs,
    c1_post regs0 regs ->
    exists regs',
      msteps ASEGS (mkst regs (0x7be8c : word) (M7 regs0) rom) (mkst regs' (0x7bf18 : word) (M7 regs0) rom)
      /\ c2_post regs' /\ keeps_but RIPL regs regs'.
Proof.
